```ts
import { updateAnimationManager } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

/**
 * Advance everything on `manager` (clips, tasks, weight fades) by exactly `ms`
 * milliseconds in a single update.
 *
 * `updateAnimationManager` replaces the delta with `fixedDeltaMs` whenever that is
 * positive, so for fixed-step managers the step is lifted for this one call and
 * restored afterwards (even if a task throws). Later frames see the same
 * `fixedDeltaMs` as before.
 */
export function skipAhead(manager: AnimationManager, ms: number): void {
    if (!Number.isFinite(ms) || ms <= 0) {
        return;
    }
    const savedFixedDeltaMs = manager.fixedDeltaMs;
    manager.fixedDeltaMs = 0;
    try {
        updateAnimationManager(manager, ms);
    } finally {
        manager.fixedDeltaMs = savedFixedDeltaMs;
    }
}
```

I added `skipAhead`, which temporarily sets `fixedDeltaMs` to 0, calls `updateAnimationManager(manager, ms)` once, then restores the original value in a `finally`. This is needed because `updateAnimationManager` ignores the delta you pass whenever `fixedDeltaMs > 0`. Fades, the category handler and all tasks therefore receive exactly `ms` in one step, and `onUpdate` and `_lastTime` are not touched.

I couldn't run anything, so this is untested. I'm also assuming `@babylonjs/lite` exports `updateAnimationManager` as a value. The `.d.ts` you gave doesn't show the package's entry point. Non-finite or non-positive `ms` is silently ignored, as `updateAnimationManager` does.
